import requests
import re

# Try to find the download link for median household income
url = "https://www.ers.usda.gov/data-products/county-level-data-sets/county-level-data-sets-download-data/"
try:
    response = requests.get(url, timeout=30)
    # Find all links with regex
    links = re.findall(r'href="([^"]*)"[^>]*>([^<]*)', response.text)
    for href, text in links:
        if 'income' in text.lower() or 'income' in href.lower():
            print(f"Link: {href} - Text: {text}")
except Exception as e:
    print(f"Error: {e}")
EOF"}

